package calc

import "testing"

func Add(a, b int) int { return a + b }

// 1) 表驱动测试
func TestAdd(t *testing.T) {
	tests := []struct {
		name string
		a, b int
		want int
	}{
		{"正数", 1, 2, 3},
		{"零值", 0, 0, 0},
		{"负数", -1, -2, -3},
		{"溢出边界", 1<<62 - 1, 1, 1 << 62},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel() // 子测试并行
			if got := Add(tt.a, tt.b); got != tt.want {
				t.Errorf("Add(%d,%d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

// 2) 示例测试:会被 go test 执行并比对输出
func ExampleAdd() {
	println(Add(1, 2))
	// Output:
	// 3
}

// 3) 基准测试:注意 ResetTimer 与 Sink
var Sink int

func BenchmarkAdd(b *testing.B) {
	b.ReportAllocs()
	b.ResetTimer() // 准备时间不计入
	for i := 0; i < b.N; i++ {
		Sink = Add(i, 1) // 赋给包级变量,防止被优化掉
	}
}

// 4) 模糊测试
func FuzzAdd(f *testing.F) {
	f.Add(1, 2)
	f.Fuzz(func(t *testing.T, a, b int) {
		if Add(a, b) != b+a {
			t.Fatalf("交换律不成立: %d + %d", a, b)
		}
	})
}

