package user

import (
	"context"
	"errors"
	"testing"
)

type User struct{ ID int; Name string }

// 接口定义在消费方(这个包需要什么就声明什么),而不是在 repo 包里
type Repo interface {
	Get(ctx context.Context, id int) (*User, error)
}

type Service struct{ repo Repo }

func NewService(r Repo) *Service { return &Service{repo: r} }

var ErrNotFound = errors.New("user not found")

func (s *Service) DisplayName(ctx context.Context, id int) (string, error) {
	u, err := s.repo.Get(ctx, id)
	if err != nil {
		return "", err
	}
	if u.Name == "" {
		return "匿名", nil
	}
	return u.Name, nil
}

// 测试里提供一个假实现,完全不碰数据库
type fakeRepo struct{ u *User; err error }

func (f fakeRepo) Get(ctx context.Context, id int) (*User, error) { return f.u, f.err }

func TestDisplayName(t *testing.T) {
	tests := []struct {
		name string
		repo fakeRepo
		id   int
		want string
		wantErr bool
	}{
		{"正常", fakeRepo{u: &User{Name: "a"}}, 1, "a", false},
		{"空名字", fakeRepo{u: &User{}}, 1, "匿名", false},
		{"查不到", fakeRepo{err: ErrNotFound}, 1, "", true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := NewService(tt.repo).DisplayName(context.Background(), tt.id)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr %v", err, tt.wantErr)
			}
			if got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

