func Idempotent(rdb *redis.Client) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := r.Header.Get("Idempotency-Key")
			if key == "" {
				// 没有幂等键就不做保护:这是「显式选择」,不是遗漏
				next.ServeHTTP(w, r)
				return
			}

			rk := "idem:" + key
			ok, err := rdb.SetNX(r.Context(), rk, "processing", 10*time.Minute).Result()
			if err != nil {
				http.Error(w, "internal error", http.StatusInternalServerError)
				return
			}
			if !ok {
				// 抢占失败 = 已有同键请求在处理或已处理完
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusConflict)
				_, _ = w.Write([]byte(`{"code":409,"msg":"duplicate request"}`))
				return
			}

			// 成功则保留 key(窗口内后续重复请求都会被拦);
			// 失败则删除,允许客户端用同一个 key 重试
			committed := false
			defer func() {
				if !committed {
					// 删 key 时用独立 context:请求的 ctx 可能已取消
					_ = rdb.Del(context.WithoutCancel(r.Context()), rk).Err()
				}
			}()

			next.ServeHTTP(w, r)

			// 只有「业务确实成功」才保留 key。
			// 真实项目用 responseWriter 包装器捕获状态码,
			// 这里简化成「handler 正常返回即视为成功」。
			committed = true
		})
	}
}

// 为什么还需要数据库唯一索引:
//  1. Redis 可能不可用 —— 降级时幂等保护直接失效;
//  2. Redis 被淘汰/清空 —— 10 分钟窗口内也可能丢;
//  3. 进程在「抢到 key 但还没写库」时崩溃 —— 重启后 key 还在,业务却没做,
//     客户端拿同一个 key 重试会被误判为「重复」。
// 因此正确做法是双保险:
//   Redis 负责「挡住并发重复」(性能层),
//   唯一索引负责「保证状态不被重复修改」(正确性层)。
//  即使 Redis 全挂,唯一索引也能让第二次插入失败,业务当作成功返回。

