type call struct {
	wg  sync.WaitGroup
	val any
	err error
}

type Group struct {
	mu sync.Mutex
	m  map[string]*call
}

func (g *Group) Do(key string, fn func() (any, error)) (any, error) {
	g.mu.Lock()
	if g.m == nil {
		g.m = make(map[string]*call)
	}

	// 命中:同 key 已有请求在执行,合并等待
	if c, ok := g.m[key]; ok {
		g.mu.Unlock()
		c.wg.Wait()
		return c.val, c.err
	}

	c := new(call)
	c.wg.Add(1)
	g.m[key] = c
	g.mu.Unlock()

	// 关键:fn 在锁外执行,否则所有 key 都被串行化
	defer func() {
		c.wg.Done()          // 先唤醒等待者
		g.mu.Lock()
		delete(g.m, key)     // 再删 key:失败后允许重试
		g.mu.Unlock()
	}()

	c.val, c.err = fn()
	return c.val, c.err
}

// 三个容易写错的点:
//  1. c.wg.Wait() 必须在 Unlock 之后 —— 否则持锁等待,先到的请求
//     删 key 时永远拿不到锁,死锁。
//  2. delete 必须在 wg.Done() 之后 —— 否则新请求可能在「结果还没写入」
//     时就拿到同一个 call,读到 nil。
//  3. fn 不能接收「第一个请求的 ctx」—— 那个 ctx 一旦超时,
//     所有等待者会被一起取消,包括本来还能成功的请求。

