func UnaryInterceptor(logger *slog.Logger) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req any, info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler) (resp any, err error) {

		start := time.Now()

		// 1) trace id:有就继承,没有就生成;两种都要写回响应头
		var traceID string
		if md, ok := metadata.FromIncomingContext(ctx); ok {
			if v := md.Get("x-trace-id"); len(v) > 0 {
				traceID = v[0]
			}
		}
		if traceID == "" {
			traceID = fmt.Sprintf("%d-%d", time.Now().UnixNano(), rand.Int63())
		}
		_ = grpc.SetHeader(ctx, metadata.Pairs("x-trace-id", traceID))

		// 2) 只在「没有 deadline」时补默认超时,绝不覆盖调用方的预算
		if _, hasDeadline := ctx.Deadline(); !hasDeadline {
			var cancel context.CancelFunc
			ctx, cancel = context.WithTimeout(ctx, 5*time.Second)
			defer cancel()
		}

		// 3) panic 不能打穿 server
		defer func() {
			if r := recover(); r != nil {
				logger.Error("panic in handler",
					"method", info.FullMethod, "trace_id", traceID, "panic", r)
				err = status.Errorf(codes.Internal, "internal error")
			}
		}()

		resp, err = handler(ctx, req)

		// 4) 耗时 + 状态码
		code := codes.OK
		if err != nil {
			if st, ok := status.FromError(err); ok {
				code = st.Code()
			} else {
				code = codes.Unknown
			}
		}
		logger.Info("grpc",
			"method", info.FullMethod,
			"code", code.String(),
			"cost_ms", time.Since(start).Milliseconds(),
			"trace_id", traceID,
		)
		return resp, err
	}
}

// 三个容易写错的点:
//  1. 无条件 WithTimeout 会「缩短」调用方的 deadline ——
//     调用方给 100ms,你包 5s 没影响;但调用方给 3s,你包 100ms 就直接掐断了。
//  2. panic 必须 recover:gRPC 默认不 recover,一次 nil map 写入能杀掉整个服务。
//  3. SetHeader 必须在 handler 返回前调用(响应头一旦发出就改不了了)。

