const alphabet = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

const codeLen = 7

var decodeTable [256]int8

func init() {
	for i := range decodeTable {
		decodeTable[i] = -1
	}
	for i := 0; i < len(alphabet); i++ {
		decodeTable[alphabet[i]] = int8(i)
	}
}

func Encode(id int64) (string, error) {
	if id < 0 {
		return "", fmt.Errorf("negative id: %d", id)
	}
	if id == 0 {
		return strings.Repeat("0", codeLen), nil
	}

	buf := make([]byte, 0, codeLen)
	for id > 0 {
		buf = append(buf, alphabet[id%62])
		id /= 62
	}
	// buf 现在是「低位在前」,反转
	for i, j := 0, len(buf)-1; i < j; i, j = i+1, j-1 {
		buf[i], buf[j] = buf[j], buf[i]
	}
	if len(buf) > codeLen {
		return "", fmt.Errorf("id too large for %d chars", codeLen)
	}
	// 左补 '0' 到定长:'0' 对应数值 0,不改变解码结果
	pad := codeLen - len(buf)
	if pad > 0 {
		buf = append(make([]byte, pad), buf...)
		for i := 0; i < pad; i++ {
			buf[i] = '0'
		}
	}
	return string(buf), nil
}

func Decode(s string) (int64, error) {
	if len(s) == 0 || len(s) > 10 {
		return 0, fmt.Errorf("bad length: %d", len(s))
	}
	var val int64
	for i := 0; i < len(s); i++ {
		d := decodeTable[s[i]]
		if d < 0 {
			return 0, fmt.Errorf("invalid char %q at %d", s[i], i)
		}
		// 溢出检查:val*62 + d 必须 <= MaxInt64
		if val > (math.MaxInt64-int64(d))/62 {
			return 0, fmt.Errorf("overflow at %d", i)
		}
		val = val*62 + int64(d)
	}
	return val, nil
}

// 三个容易被追问的点:
//  1. 为什么定长?"0000abc" 和 "abc" 解码结果相同,但定长让
//     「存储列宽、索引长度、校验规则」都固定下来,少了分支判断。
//  2. 连续 ID 的短码也是连续的 —— 别人可以「顺着猜」。所以生产上
//     要么用雪花 ID(非连续),要么在 Base62 之前做一次可逆混淆
//     (如乘以一个大奇数再取模),让短码看起来随机。
//  3. 自定义后缀(如 t.cn/mygift)必须和发号空间隔离,
//     否则会撞号 —— 通常用单独的「短码 -> 长链」表 + 唯一索引。
